"""Read-only guard for SQL statements generated by the AI assistant.

Conservative by design: anything the tokenizer cannot model unambiguously
(backslashes in strings, dollar-quoting, unterminated constructs, malformed
WITH clauses) is rejected rather than accepted.
"""

import re

__all__ = ["UnsafeSQLError", "assert_read_only"]


class UnsafeSQLError(ValueError):
    """Raised when a SQL statement is not guaranteed to be read-only."""


_WRITE_KEYWORDS = (
    "insert",
    "update",
    "delete",
    "drop",
    "alter",
    "create",
    "truncate",
    "grant",
    "revoke",
    "copy",
    "attach",
    "pragma",
    "do",
    "merge",
    "call",
    "comment",
    "vacuum",
    "analyze",
    "set",
    "reset",
)

# Conservative: any read_*/*_scan-style file function, plus known Postgres
# file/sequence functions. False positives are acceptable for a read-only guard.
_FORBIDDEN_FUNCTION_RE = re.compile(
    r"\b(?:read_\w+|\w+_scan|glob|pg_\w*(?:read|write)\w*|pg_ls_\w+"
    r"|lo_import|lo_from_bytea|sqlite_attach|setval|nextval)\s*\(",
    re.IGNORECASE,
)

_SELECT_INTO_RE = re.compile(r"\binto\b", re.IGNORECASE)
_FOR_UPDATE_RE = re.compile(
    r"\bfor\s+(?:no\s+key\s+)?update\b|\bfor\s+(?:key\s+)?share\b", re.IGNORECASE
)
_EXPLAIN_RE = re.compile(r"explain\b", re.IGNORECASE)
_EXPLAIN_ANALYZE_RE = re.compile(r"\banalyze\b", re.IGNORECASE)
_SELECT_OR_WITH_RE = re.compile(r"(?:select|with)\b", re.IGNORECASE)

_DOLLAR_QUOTE_RE = re.compile(r"\$\$|\$[A-Za-z_][A-Za-z0-9_]*\$")

_WITH_RE = re.compile(r"with\b", re.IGNORECASE)
_RECURSIVE_RE = re.compile(r"recursive\b", re.IGNORECASE)
_AS_RE = re.compile(r"as\b", re.IGNORECASE)
_IDENTIFIER_RE = re.compile(r"[A-Za-z_]\w*")
_WRITE_START_RE = re.compile(rf"({'|'.join(_WRITE_KEYWORDS)})\b", re.IGNORECASE)


def _clean(sql: str) -> str:
    """Blank out string literals and comments.

    Rejects (rather than guesses) constructs whose semantics vary between
    engines: backslashes in strings, doubled-quote escapes near semicolons,
    dollar-quoting, and unterminated strings/comments.
    """
    out = []
    i, n = 0, len(sql)
    while i < n:
        ch = sql[i]
        if ch in "'\"":
            quote = ch
            i += 1
            content = []
            closed = False
            has_doubled_quote = False
            while i < n:
                if sql[i] == "\\":
                    raise UnsafeSQLError("Backslash in string literal is ambiguous")
                if sql[i] == quote:
                    if i + 1 < n and sql[i + 1] == quote:
                        has_doubled_quote = True
                        content.append(quote)
                        i += 2
                        continue
                    closed = True
                    i += 1
                    break
                content.append(sql[i])
                i += 1
            if not closed:
                raise UnsafeSQLError("Unterminated string literal")
            if has_doubled_quote and ";" in content:
                raise UnsafeSQLError("Ambiguous escaped quote near semicolon")
            out.append(" ")
        elif sql[i : i + 2] == "--":
            while i < n and sql[i] != "\n":
                i += 1
        elif sql[i : i + 2] == "/*":
            end = sql.find("*/", i + 2)
            if end == -1:
                raise UnsafeSQLError("Unterminated block comment")
            i = end + 2
            out.append(" ")
        elif ch == "$" and _DOLLAR_QUOTE_RE.match(sql, i):
            raise UnsafeSQLError("Dollar-quoted bodies are not allowed")
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def _take_group(text: str) -> tuple[str, str]:
    """Split a leading balanced parenthesized group; return (inner, rest)."""
    depth = 0
    for pos, ch in enumerate(text):
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                return text[1:pos], text[pos + 1 :]
    raise UnsafeSQLError("Unbalanced parentheses")


def _parse_ctes(rest: str) -> str:
    """Consume leading WITH [RECURSIVE] <name>[(cols)] AS (<body>)[, ...] clauses."""
    rest = _WITH_RE.sub("", rest, count=1).lstrip()
    if _RECURSIVE_RE.match(rest):
        rest = _RECURSIVE_RE.sub("", rest, count=1).lstrip()
    while True:
        match = _IDENTIFIER_RE.match(rest)
        if not match:
            raise UnsafeSQLError("Malformed WITH clause")
        rest = rest[match.end() :].lstrip()
        if rest.startswith("("):
            inner, rest = _take_group(rest)
            _check_statement(inner)
            rest = rest.lstrip()
        match = _AS_RE.match(rest)
        if not match:
            raise UnsafeSQLError("Malformed WITH clause: expected AS")
        rest = rest[match.end() :].lstrip()
        if not rest.startswith("("):
            raise UnsafeSQLError("CTE body must be parenthesized")
        inner, rest = _take_group(rest)
        _check_statement(inner)
        rest = rest.lstrip()
        if rest.startswith(","):
            rest = rest[1:].lstrip()
            continue
        return rest


def _check_statement(statement: str, *, top_level: bool = False) -> None:
    """Validate a single (string/comment-free) statement.

    ``top_level`` is True only for the statement as a whole; nested paren
    group inners may legitimately be blank (e.g. a lone string literal).
    """
    pos = 0
    while pos < len(statement):
        if statement[pos] == "(":
            inner, remaining = _take_group(statement[pos:])
            _check_statement(inner)
            pos = len(statement) - len(remaining)
        else:
            pos += 1
    if _FORBIDDEN_FUNCTION_RE.search(statement):
        raise UnsafeSQLError("Forbidden file function call")
    if _FOR_UPDATE_RE.search(statement):
        raise UnsafeSQLError("Locking clause is not allowed")
    rest = statement.strip()
    if _WITH_RE.match(rest):
        rest = _parse_ctes(rest)
    while rest.startswith("("):
        _, rest = _take_group(rest)
        rest = rest.lstrip()
    if not rest:
        if top_level:
            raise UnsafeSQLError("Empty statement body")
        return
    if _WRITE_START_RE.match(rest):
        raise UnsafeSQLError("Write keyword at statement start")
    if _EXPLAIN_RE.match(rest):
        _check_explain(rest, top_level=top_level)
        return
    if rest.lower().startswith("select"):
        if _SELECT_INTO_RE.search(rest):
            raise UnsafeSQLError("SELECT INTO creates a table")


def _check_explain(rest: str, *, top_level: bool) -> None:
    """Validate an EXPLAIN statement: no ANALYZE, and only SELECT/WITH inside."""
    if _EXPLAIN_ANALYZE_RE.search(rest):
        raise UnsafeSQLError("EXPLAIN ANALYZE executes the statement")
    remainder = _EXPLAIN_RE.sub("", rest, count=1).lstrip()
    if remainder.startswith("("):
        _, remainder = _take_group(remainder)
        remainder = remainder.lstrip()
    if not _SELECT_OR_WITH_RE.match(remainder):
        raise UnsafeSQLError("EXPLAIN is only allowed on SELECT/WITH")
    _check_statement(remainder, top_level=top_level)


def assert_read_only(sql: str) -> None:
    """Raise UnsafeSQLError unless sql is a single read-only statement."""
    cleaned = _clean(sql)
    statements = [s for s in cleaned.split(";") if s.strip()]
    if len(statements) > 1:
        raise UnsafeSQLError("Multiple SQL statements are not allowed")
    if not statements:
        raise UnsafeSQLError("Empty SQL statement")
    _check_statement(statements[0], top_level=True)
